488 	if controller < 0 || controller >= len(gs.Players) {
489 		return 0, false
490 	}
491 	n, ok := gs.evalDynamicAmountBase(spec, controller, source, eventCard, targets)
492 	if !ok {
493 		return 0, false
494 	}
495 	// Reversed subtractive form (ticket
496 	// engine.auto-triggered-dynamic-amount-damage-to-player-951be52163,
497 	// Storm World class: "X is 4 minus the number of cards in their
498 	// hand"). Unlike "minus" below (resolved count minus a constant),
499 	// "from" subtracts the resolved count FROM a constant base — the
500 	// mirror-image shape needed for expressions like "4 minus hand size".
501 	// Floors at 0 the same way "minus" does, via the shared floor below.
502 	if f, isNum := spec["from"].(float64); isNum {
503 		n = int(f) - n
504 	} else if f, isInt := spec["from"].(int); isInt {
505 		n = f - n
506 	}
507 	// Optional additive offset ("one plus the number of ...").
508 	if p, isNum := spec["plus"].(float64); isNum {
509 		n += int(p)
510 	} else if p, isInt := spec["plus"].(int); isInt {
511 		n += p
512 	}
513 	// Optional subtractive offset (ticket
514 	// engine.auto-damage-amount-from-cards-in-hand-minus-constant-2fdd0137de,
515 	// Iron Maiden/Black Vise/The Rack class: "X is the number of cards in
516 	// their hand minus 4"). Floors at 0 (Rule 107.3b: a variable amount
517 	// that would be negative is treated as 0 unless otherwise specified),
518 	// unlike "plus" above which never needs a floor.
519 	if m, isNum := spec["minus"].(float64); isNum {
520 		n -= int(m)
521 	} else if m, isInt := spec["minus"].(int); isInt {
522 		n -= m
523 	}
524 	if n < 0 {
525 		n = 0
526 	}
527 	return n, true
